def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Find background components, and fill those that do not touch the edge.
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            component = []
            q = deque([(r, c)])
            seen.add((r, c))
            touches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == bg and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out
